mapper.select:
select seq, id, ref, step, depth, title, content, wdate, parent, del, readcount from bbs
where title like concat('%', #{keyword}, '%')
where content like concat('%', #{keyword}, '%')
where id=#{keyword}
order by ref desc, step asc limit 10 offset ${(pageNumber * 10)}

select seq, id, ref, step, depth, title, content, wdate, parent, del, readcount
from bbs
where seq=#{seq}
